import {useEffect, useState} from 'react';
import Snackbar from 'react-native-snackbar';
import {useIsFocused, useNavigation} from '@react-navigation/native';
import {AuthNavigationProps} from '../../navigation/stacks/authStack';
import {axiosInstance} from '../../services/api/api';
import constant from '../../services/config/constant';
import {RewardsControllerProps} from './rewards.interface';
import {Keyboard} from 'react-native';
import Log from '../../utility/log';
import {useAppSelector} from '../../services/config/redux/useReduxHooks';

const RewardsController = (): RewardsControllerProps => {
  const isFocused = useIsFocused();
  const [loading, setLoading] = useState<boolean>(false);
  const [search, setSearch] = useState<string>('');
  const [list, setList] = useState<any[]>([]);
  const [staticList, setStaticList] = useState<any[]>([]);
  const [refreshing, setRefreshing] = useState<boolean>(false);
  const {token} = useAppSelector(state => state.UserReducer);
  const navigation = useNavigation<AuthNavigationProps>();

  useEffect(() => {
    getRewardList();
  }, []);

  const refreshJob = (): void => {
    setRefreshing(true);
    getRewardList();
  };

  useEffect(() => {
    if (isFocused) {
      Keyboard.dismiss();
      setSearch('');
      setList(staticList);
    }
  }, [isFocused]);

  const handleSearch = (text: string) => {
    setSearch(text);
    const filter = staticList?.filter((item: any) => {
      const itemData = `${item?.transactionId?.movieId?.name} ${item?.transactionId?.initTransId}`;
      const textData = text.toLowerCase();
      return itemData.toLowerCase().includes(textData);
    });
    setList(filter);
  };

  const onClear = () => {
    setSearch('');
    setList(staticList);
  };

  const getRewardList = async () => {
    setLoading(true);
    try {
      const {data} = await axiosInstance.get(constant.getRewards, {
        headers: {
          auth: token,
        },
      });
      setList(data?.data);
      setStaticList(data?.data);
      setLoading(false);
      setRefreshing(false);
    } catch (error: any) {
      setLoading(false);
      setRefreshing(false);
      Snackbar.show({text: error?.response?.data?.message ?? error?.message});
      Log(
        'getRewardList error',
        error?.response?.data?.message ?? error?.message,
      );
    }
  };

  const onClick = (item: any): void => {};

  return {
    list,
    loading,
    onClick,
    refreshing,
    refreshJob,
    search,
    handleSearch,
    onClear,
  };
};

export default RewardsController;
