import React from 'react';
import {
  ActivityIndicator,
  FlatList,
  Image,
  RefreshControl,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import {CustomStatusBar, Header, Input} from '../../components';
import {color} from '../../theme';
import commonFunctions from '../../utility/functions/commonFunctions/commonFunctions';
import style from './Rewards.style';
import moment from 'moment';
import RewardsController from './rewards.controller';
import svgIndex from '../../assets/svgIndex';
import imageIndex from '../../assets/imageIndex';

const Rewards: React.FC = () => {
  const {
    list,
    loading,
    onClick,
    refreshing,
    refreshJob,
    search,
    handleSearch,
    onClear,
  } = RewardsController();
  const {onBack} = commonFunctions();

  const renderData = (item: any, index: number) => {
    return (
      <TouchableOpacity
        style={style.parentView}
        activeOpacity={0.7}
        onPress={() => onClick(item)}>
        <View style={style.divider}>
          <Text allowFontScaling={false} style={style.movieText}>
            {item?.transactionId?.movieId?.name}
          </Text>
          <View style={style.coinDivider}>
            <Image style={style.rewardImage} source={imageIndex.rewards} />
            <Text allowFontScaling={false} style={style.rewardsText}>
              {item?.coins}
            </Text>
          </View>
        </View>
        <View style={style.lineView} />
        <View style={style.content}>
          <Text style={style.titleText}>Booking Id: </Text>
          <Text allowFontScaling={false} style={style.priceDurationText}>
            {item?.transactionId?.initTransId}
          </Text>
        </View>
        <View style={style.content}>
          <Text style={style.titleText}>Date: </Text>
          <Text allowFontScaling={false} style={style.priceDurationText}>
            {moment(item?.createdAt).format('DD/MM/YYYY')}
          </Text>
        </View>
        <View style={style.content}>
          <Text style={style.titleText}>Amount: </Text>
          <Text allowFontScaling={false} style={style.priceDurationText}>
            ₹{item?.transactionId?.paymentResponse?.amount}
          </Text>
        </View>
      </TouchableOpacity>
    );
  };

  return (
    <View style={style.mainContainer}>
      <CustomStatusBar backgroundColor={color.inputBackground} />
      <Header
        backIcon
        onBack={onBack}
        title="Rewards"
        titleContainerStyle={style.title}
      />
      {!refreshing && loading ? (
        <View style={style.container}>
          <ActivityIndicator size="large" color={color.white} />
        </View>
      ) : (
        <View style={style.main}>
          <Input
            value={search}
            setValue={(text: any) => handleSearch(text?.trimStart())}
            placeholder="Search..."
            leftIcon={svgIndex.Search}
            inputContainer={style.inputContainer}
            inputMainContainer={style.inputMainContainer}
            inputStyle={style.input}
            inputProps={{placeholderTextColor: color.white}}
            rigthFilterIcon={search ? true : false}
            onPressRightFilterIcon={onClear}
          />
          <FlatList
            data={list}
            renderItem={({item, index}) => renderData(item, index)}
            showsVerticalScrollIndicator={false}
            contentContainerStyle={style.flatlistContainer}
            ListEmptyComponent={() => (
              <View style={style.container}>
                <Text allowFontScaling={false} style={style.noData}>
                  No Rewards Available
                </Text>
              </View>
            )}
            refreshControl={
              <RefreshControl
                refreshing={refreshing}
                onRefresh={refreshJob}
                tintColor={color.white}
              />
            }
          />
        </View>
      )}
    </View>
  );
};

export default Rewards;
